import 'package:flutter/material.dart';
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Zé Entregador',theme:ThemeData(useMaterial3:true,colorSchemeSeed:const Color(0xFFF4C430)),home:const Home());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{bool online=false;int step=0;final labels=['Nova entrega disponível','Cheguei ao estabelecimento','Pedido retirado','Cheguei ao cliente','Confirmar entrega','Entrega concluída'];@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Zé Entregador',style:TextStyle(fontWeight:FontWeight.bold))),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('Painel do entregador',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:16),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(children:[Icon(online?Icons.delivery_dining:Icons.power_settings_new,size:60),Text(online?'ONLINE':'OFFLINE',style:const TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const SizedBox(height:10),FilledButton(onPressed:()=>setState(()=>online=!online),child:Text(online?'FICAR OFFLINE':'FICAR ONLINE'))]))),const SizedBox(height:16),if(online)...[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(labels[step],style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Teste MVP • Vale do Capão\nCorrida demonstrativa • R\$ 8,00'),const SizedBox(height:14),FilledButton(onPressed:step<5?()=>setState(()=>step++):null,child:Text(step==0?'ACEITAR ENTREGA':step==5?'CONCLUÍDA':labels[step]))]))),const SizedBox(height:12),const Row(children:[Expanded(child:Card(child:Padding(padding:EdgeInsets.all(16),child:Column(children:[Text('R\$ 0,00',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text('Ganhos hoje')])))),Expanded(child:Card(child:Padding(padding:EdgeInsets.all(16),child:Column(children:[Text('0',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text('Entregas')]))))])]])} }
